package eu.kanade.tachiyomi.source;

import eu.kanade.tachiyomi.source.model.FilterList;
import eu.kanade.tachiyomi.source.model.Page;
import eu.kanade.tachiyomi.source.model.SChapter;
import eu.kanade.tachiyomi.source.model.SManga;
import eu.kanade.tachiyomi.source.model.SMangaUpdate;
import java.util.List;
import kotlin.coroutines.Continuation;
import rx.Observable;

/**
 * Binary-compatible host contract for extensions-lib 1.4 and TachiyomiX 1.6.
 *
 * The continuation methods intentionally use the exact JVM descriptors generated by
 * Kotlin suspend functions. Default implementations preserve 1.4 behaviour; 1.6
 * implementations can override them with real suspending implementations.
 */
public interface Source {
    long getId();
    String getName();
    String getLang();

    /** Exists on the 1.6 ABI; default keeps older 1.4 extensions loadable. */
    default boolean getSupportsLatest() { return false; }

    default FilterList getFilterList() { return new FilterList(); }

    default Observable<SManga> fetchMangaDetails(SManga manga) {
        return Observable.error(new UnsupportedOperationException("fetchMangaDetails not implemented"));
    }

    default Observable<List<SChapter>> fetchChapterList(SManga manga) {
        return Observable.error(new UnsupportedOperationException("fetchChapterList not implemented"));
    }

    default Observable<List<Page>> fetchPageList(SChapter chapter) {
        return Observable.error(new UnsupportedOperationException("fetchPageList not implemented"));
    }

    /** Kotlin: suspend fun getMangaUpdate(...): SMangaUpdate */
    default Object getMangaUpdate(
        SManga manga,
        List<SChapter> chapters,
        boolean fetchDetails,
        boolean fetchChapters,
        Continuation<? super SMangaUpdate> continuation
    ) {
        SManga resultManga = fetchDetails ? fetchMangaDetails(manga).toBlocking().first() : manga;
        List<SChapter> resultChapters = fetchChapters
            ? fetchChapterList(resultManga).toBlocking().first()
            : chapters;
        return new SMangaUpdate(resultManga, resultChapters);
    }

    /** Kotlin: suspend fun getPageList(chapter): List<Page> */
    default Object getPageList(
        SChapter chapter,
        Continuation<? super List<Page>> continuation
    ) {
        return fetchPageList(chapter).toBlocking().first();
    }
}
